    explanation: "Fluorescent light ballasts generate electromagnetic interference (EMI) that can induce noise into nearby UTP cables. Best fixes: route cables at least 6 inches from fluorescent fixtures (12 inches if parallel), use STP (shielded twisted pair) cable, or use conduit. The interference is most severe when cables run parallel to lights for long distances.",
