    explanation: "Cat6a (Augmented Category 6) is rated to 500 MHz and supports 10GBase-T for the full 100-meter horizontal run. Cat6 supports 10GBase-T but only to 55 meters (alien crosstalk becomes a problem beyond that). Cat5e supports 1 GbE only. Cat6a has tighter twist ratios and (in shielded versions) shields each pair to reduce alien crosstalk.",
    triggerPhrase: "Cat6a = 10GBase-T at full 100m (Cat6 only 55m for 10G)",
    weaknessTags: ["cat-ratings", "cabling-faults", "attenuation"],
