    explanation: "Impact (dot-matrix) printers use a printhead with pins that physically strike an inked ribbon against paper. This physical impact transfers ink and simultaneously presses through multiple layers of NCR (No Carbon Required) paper or actual carbon paper. Laser and inkjet printers only print on the top sheet. Thermal printers only work with special paper. Impact printers are still used in: automotive service (multi-part invoices), shipping/logistics, restaurants (kitchen tickets), banking, and any application requiring simultaneous multiple copies.",
