    explanation: "TCO comparison: Inkjet: low upfront cost ($50-200), but ink cartridges yield 200-500 pages and dry out when unused, requiring cleaning cycles. CPP (cost per page) can be $0.10-0.25 per page. Laser: higher upfront ($200-800+), but toner cartridges yield 2,000-25,000+ pages, toner doesn't dry out, faster printing, lower CPP ($0.01-0.05). For low-volume home users who print infrequently, inkjet may actually be cheaper despite higher CPP due to lower purchase price. For office use, laser wins on TCO.",
