    explanation: "Ghost images (secondary images, shadowing): occur when residual toner from a previous print cycle is not fully removed or residual charge on the drum causes re-imaging. Causes: worn cleaning blade (doesn't scrape drum clean), worn/contaminated drum that retains charge patterns, or a cold fuser (toner not fully fused, remaining on the fuser rollers and transferring to subsequent pages). The interval of ghosting indicates the drum circumference (drum ghost) or fuser roller circumference. Replace drum unit or fuser based on interval measurement.",
    triggerPhrase: "Ghost/shadow image at regular intervals = worn drum (cleaning blade) or fuser contamination; interval = drum or fuser circumference",
    weaknessTags: ["print-quality-issues", "laser-maintenance"],
