    explanation: "Toner smearing/wiping off pages: in a correctly functioning laser printer, the fuser permanently bonds toner to paper using heat (~200Â°C) and pressure. If you can smear toner with your finger after printing, the fuser is not fusing properly. Causes: fuser temperature sensor failed (fuser running cold), fuser heating element burned out, wrong paper type (heavy cardstock may need more fusing time), or a cold printer startup printing before fuser reaches temperature. Replace the fuser assembly. Verify paper type setting in printer driver matches actual paper.",
