    explanation: "Double-feeding (multiple sheets picked at once) is caused by a worn separation pad or separation roller. The separation pad/roller works against the pickup roller to ensure only one sheet is fed at a time â€” the pickup roller moves sheets forward while the separation pad applies friction to hold back the sheets beneath. When the pad is worn smooth, friction is reduced and multiple sheets slide through together. The separation pad is typically included in maintenance kits and is relatively inexpensive to replace.",
